          notify(ctx.ui, `Paused run ${runId}`, "warning");
        });
        return;
      }

      if (isResumableRun(payload.run.status)) {
        runAction(`Resuming run ${runId}…`, async () => {
          await apiFetchJson(baseUrl, `/api/pipeline/runs/${runId}/resume`, { method: "POST", token });
          notify(ctx.ui, `Resumed run ${runId}`, "success");
        });
      }
    };

    const attachRetryRun = (response: RetryResponse) => {
      const nextRunId = Number(response.runId);
      if (Number.isFinite(nextRunId) && nextRunId > 0) {
        runId = nextRunId;
        selectedStoryId = null;
        selectedOutput = null;
        selectedOutputError = null;
        statusLine = `Attached to retry run ${runId}`;
        notify(ctx.ui, `Attached to retry run ${runId}`, "success");
      }
    };

    const retryFailedStories = () => {
      if (!payload || !isRetryableRun(payload.run.status)) {
        return;
      }

      const failedStoryIds = collection.stories
        .filter((story) => {
          const status = normalizeStatus(story.status);
          return status === "failed" || status === "skipped";
        })
        .map((story) => story.id);

      if (failedStoryIds.length === 0) {
        statusLine = "No failed or skipped stories to retry.";
        requestRender();
        return;
      }

      runAction(`Retrying ${failedStoryIds.length} stories…`, async () => {
        const confirmed = await confirmOrProceed(
          "Retry failed stories",
          `Queue a retry for ${failedStoryIds.length} failed or skipped stories?`,
        );
        if (!confirmed) {
          statusLine = "Retry cancelled.";
          return;
        }

        const response = await apiFetchJson<RetryResponse>(baseUrl, `/api/pipeline/runs/${runId}/retry`, {
          method: "POST",
          token,
          body: { storyIds: failedStoryIds },
        });

        attachRetryRun(response);
      });
    };

    const retrySelectedStory = () => {
      if (!payload || !isRetryableRun(payload.run.status)) {
        return;
      }

      const selectedStory = collection.stories.find((story) => story.id === selectedStoryId);
      if (!isRetryableStory(selectedStory)) {
        statusLine = "Focused story is not failed or skipped.";
        requestRender();
        return;
      }

      const storyToRetry = selectedStory;
      if (!storyToRetry) {
        statusLine = "Focused story is unavailable.";
        requestRender();
        return;
      }

      runAction(`Retrying ${storyToRetry.id}…`, async () => {
        const confirmed = await confirmOrProceed("Retry focused story", `Queue a retry for ${storyToRetry.id}?`);
        if (!confirmed) {
          statusLine = "Focused story retry cancelled.";
          return;
        }

        const response = await apiFetchJson<RetryResponse>(baseUrl, `/api/pipeline/runs/${runId}/retry`, {
          method: "POST",
          token,
          body: { storyIds: [storyToRetry.id] },
        });

        attachRetryRun(response);
      });
    };

    const retryMerge = () => {
      if (!canRetryMerge(payload)) {
        return;
      }

      runAction(`Retrying merge for run ${runId}…`, async () => {
        const confirmed = await confirmOrProceed("Retry failed merge", `Retry the failed auto-merge for run ${runId}?`);
        if (!confirmed) {
          statusLine = "Merge retry cancelled.";
          return;
        }

        await apiFetchJson(baseUrl, `/api/pipeline/runs/${runId}/retry-merge`, {
          method: "POST",
          token,
        });
        notify(ctx.ui, `Queued merge retry for run ${runId}`, "success");
      });
    };

    void (async () => {
      try {
        await syncRun();
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        statusLine = `Failed to load run ${runId}: ${message}`;
        notify(ctx.ui, message, "error");
      } finally {
        busy = false;
        scheduleRefresh();
        requestRender();
      }
    })();

    return {
      handleInput(data: string) {
        const key = normalizeKey(data);

        if (key === "q" || key === "escape" || key === "ctrl+c") {
          close();
          return;
        }

        if (key === "tab") {
          cyclePane();
          return;
        }

        if (key === "?" || key === "h") {
          toggleHelp();
          return;
        }

        if (busy) {
          return;
        }

        if (key === "down" || key === "j") {
          selectStory(1);
          return;
        }

        if (key === "up" || key === "k") {
          selectStory(-1);
          return;
        }

        if (key === "r") {
          refreshNow();
          return;
        }

        if (key === "u") {
          focusCurrentStory();
          return;
        }

        if (key === "x") {
          focusNextFailedStory();
          return;
        }

        if (key === "n") {
          focusNextReadyStory();
          return;
        }

        if (key === "b") {
          focusNextBlockedStory();
          return;
        }

        if (key === "a") {
          focusActiveWave();
          return;
        }

        if (key === ",") {
          focusAdjacentWave(-1);
          return;
        }

        if (key === ".") {
          focusAdjacentWave(1);
          return;
        }

        if (key === "[") {
          switchRun(1);
          return;
        }

        if (key === "]") {
          switchRun(-1);
          return;
        }

        if (/^[1-6]$/.test(key)) {
          switchToRecentRun(Number(key) - 1);
          return;
        }

        if (key === "c") {
          cancelRun();
          return;
        }

        if (key === "p") {
          pauseOrResumeRun();
          return;
        }

        if (key === "f") {
          retryFailedStories();
          return;
        }

        if (key === "s") {
          retrySelectedStory();
          return;
        }

        if (key === "m") {
          retryMerge();
          return;
        }

        if (key === "o") {
          setPane("output");
          return;
        }

        if (key === "t") {
          setPane("story");
          return;
        }

        if (key === "v") {
          setPane("run");
          return;
        }

        if (key === "e") {
          setPane("events");
          return;
        }

        if (key === "l") {
          openRunLog();
          return;
        }

        if (key === "g") {
          openRunCommits();
          return;
        }
      },

      render(width: number): string[] {
        const safeWidth = Math.max(60, width);
        const selectedStory = collection.stories.find((story) => story.id === selectedStoryId);
        const specSlug = extractSpecSlug(payload?.run.spec_path);
        const counts = countStatuses(collection.stories);
        const failedStories = collection.stories.filter((story) => normalizeStatus(story.status) === "failed");
        const currentStory = payload?.runState?.currentStory ?? collection.stories.find((story) => normalizeStatus(story.status) === "running")?.id ?? null;
        const activeWave = findActiveWave(collection.waves);
        const activeWaveSummary = activeWave ? summarizeWaveProgress(activeWave.stories) : null;
        const header = [
          truncate(`Rorca Run Cockpit — Run ${runId}`, safeWidth),
          truncate(
            `Status ${payload ? formatStatus(payload.run.status) : "loading"} • Workspace ${workspaceLabel} • Spec ${specSlug} • Started ${payload?.run.started_at ? timeAgo(payload.run.started_at) : "unknown"}`,
            safeWidth,
          ),
          truncate(
            `Pane ${showHelp ? `${pane} + help` : pane} • Focus ${selectedStory?.id ?? currentStory ?? "none"} • Last sync ${lastSyncAt ? timeAgo(lastSyncAt) : "pending"} • Auto-refresh ${Math.round(getRefreshIntervalMs(payload, pane) / 1000)}s`,
            safeWidth,
          ),
          truncate(
            `Stories ${collection.stories.length} • ${counts.get("running") ?? 0} running • ${counts.get("passed") ?? 0} passed • ${counts.get("failed") ?? 0} failed • Tokens ${formatTokens(payload?.tokenSummary?.inputTokens)} / ${formatTokens(payload?.tokenSummary?.outputTokens)} • ${formatCurrency(payload?.tokenSummary?.totalCostUsd)}`,
            safeWidth,
          ),
          truncate(
            failedStories.length > 0
              ? `Attention: ${failedStories.length} failed • ${failedStories.slice(0, 2).map((story) => story.id).join(", ")}${failedStories.length > 2 ? " …" : ""}`
              : currentStory
                ? `Active story: ${currentStory}`
                : payload?.run.merge_status === "failed"
                  ? "Attention: auto-merge failed — press m to retry merge"
                  : "No active alerts.",
            safeWidth,
          ),
          truncate(
            activeWave && activeWaveSummary
              ? `Wave ${activeWave.index + 1}/${Math.max(1, collection.waves.length)} • ${activeWaveSummary.done}/${activeWaveSummary.total} complete • ${activeWaveSummary.running} running • ${activeWaveSummary.pending} waiting`
              : "Wave view unavailable.",
            safeWidth,
          ),
          "",
        ];

        const leftLines = renderStoryList(collection.stories, collection.waves, selectedStoryId, Math.max(24, Math.floor(safeWidth * 0.43)));
        const rightWidth = safeWidth >= 100 ? Math.max(28, safeWidth - Math.max(28, Math.floor(safeWidth * 0.43)) - 3) : safeWidth;
        const rightLines =
          pane === "output"
            ? buildOutputPane(selectedStory, selectedOutput, selectedOutputError, rightWidth)
            : pane === "story"
              ? buildStoryPane(selectedStory, collection.stories, payload?.runState, selectedOutput, rightWidth)
              : pane === "run"
                ? buildRunPane(payload, workspaceLabel, collection.stories, collection.waves, rightWidth, workspaceRuns, workspaceRunsError)
                : pane === "events"
                  ? buildEventsPane(payload, collection.stories, rightWidth)
                  : pane === "log"
                    ? buildLogPane(runLogLines, runLogError, rightWidth)
                    : buildCommitsPane(runCommits, runCommitsBranchName, runCommitsError, rightWidth);

        const activeRightLines = showHelp
          ? buildHelpPane(payload, selectedStory, rightWidth)
          : rightLines;

        const body = safeWidth >= 100
          ? renderBodyColumns(leftLines, activeRightLines, safeWidth)
          : [
              ...leftLines.map((line) => truncate(line, safeWidth)),
              "",
              ...activeRightLines.map((line) => truncate(line, safeWidth)),
            ];

        const controls: string[] = [
          "j/k move",
          "u active",
          "x next failed",
          "n next ready",
          "b next blocked",
          "a active wave",
          ",/. waves",
          "tab cycle panes",
          "o output",
          "t story",
          "v run",
          "e events",
          "[ older",
          "] newer",
          "1-6 recent",
          "l log",
          "g commits",
          "r refresh",
          "? help",
          "q close",
        ];
        if (payload && isPausableRun(payload.run.status)) {
          controls.push("p pause");
        } else if (payload && isResumableRun(payload.run.status)) {
          controls.push("p resume");
        }
        if (payload && isCancellableRun(payload.run.status)) {
          controls.push("c cancel");
        }
        if (payload && isRetryableRun(payload.run.status)) {
          controls.push("f retry failed");
          if (isRetryableStory(selectedStory)) {
            controls.push("s retry story");
          }
        }
        if (canRetryMerge(payload)) {
          controls.push("m retry merge");
        }

        return [
          ...header,
          ...body,
          "",
          truncate(statusLine, safeWidth),
          truncate(controls.join(" • "), safeWidth),
        ];
      },

      invalidate() {
        // Stateless rendering.
      },
    };
  });
}

